import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.BqDA2HS7.js";const b=JSON.parse('{"title":"自适应最终审核","description":"","frontmatter":{},"headers":[],"relativePath":"adaptive-review.md","filePath":"adaptive-review.md"}'),o={name:"adaptive-review.md"};function i(h,t,l,n,p,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="自适应最终审核" tabindex="-1">自适应最终审核 <a class="header-anchor" href="#自适应最终审核" aria-label="Permalink to &quot;自适应最终审核&quot;">​</a></h1><p>这是自动路由的最终候选审核，独立于规划 Advisor／Escalation 的设置与状态。 当前规则为 <code>adaptive-final-review-v1</code>，适用于新版人民币参考计价配置。</p><h2 id="哪些任务需要审核" tabindex="-1">哪些任务需要审核 <a class="header-anchor" href="#哪些任务需要审核" aria-label="Permalink to &quot;哪些任务需要审核&quot;">​</a></h2><p>预检先保护可能需要的审核路径。最终候选形成后，根据原任务风险与实际证据决定派发：</p><table tabindex="0"><thead><tr><th>情况</th><th>行为</th></tr></thead><tbody><tr><td>低风险 Direct，未出现额外风险</td><td>可以跳过付费审核，记录跳过原因</td></tr><tr><td>DAG、明确资料与验收合同、事实查证等</td><td>保留审核</td></tr><tr><td>实际工具结果、引用、候选断言实现／验证状态</td><td>纳入审核风险检查</td></tr><tr><td>仅仅注册了可用工具</td><td>不单独触发最终审核</td></tr><tr><td>选择始终审核</td><td>每次保留审核</td></tr></tbody></table><p>规则决定是否增加审核，不凭关键词直接认定事实错误或答案通过。 预检未保护的微型路径出现新审核风险时停止交付，不能事后任意扩大调用路径。</p><h2 id="审核材料怎样组织" tabindex="-1">审核材料怎样组织 <a class="header-anchor" href="#审核材料怎样组织" aria-label="Permalink to &quot;审核材料怎样组织&quot;">​</a></h2><p>完整任务、候选、验收条件与工具记录按值去重，保留原始数值、文本、来源、工具参数、 调用与结果配对。候选与来源分开，候选不能用自身为事实自证。 材料不截断、不隐式摘要，不增加摘要模型调用。派发前核对实际模型上下文和明确输出上限。</p><p>公开合成夹具输入由 239426 降至 104200 字节，完整工具值还原相等。 这是该夹具的结果，不代表所有任务同比节省费用或提高准确率。</p><h2 id="不同失败如何处理" tabindex="-1">不同失败如何处理 <a class="header-anchor" href="#不同失败如何处理" aria-label="Permalink to &quot;不同失败如何处理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>核心结果</th><th>后续行为</th></tr></thead><tbody><tr><td>明确候选缺陷</td><td>若已启用最终纠正，原执行器纠正一次，再复审</td></tr><tr><td>证据检查无法判断</td><td>未审定停止，不用文字补造证据</td></tr><tr><td>没有明确缺陷但分数未达门槛</td><td>停止，不盲目返工</td></tr><tr><td>非法审核、认证／传输故障或未知用量</td><td>停止后续调用，保留错误与费用</td></tr></tbody></table><p>纠正不重建 DAG、不重跑已完成工具、不追加子 Agent。 自动路由最终审核的结论不会反向改变已完成节点的选模；规划 Escalation 的接管是另一策略。</p><h2 id="时间与额度" tabindex="-1">时间与额度 <a class="header-anchor" href="#时间与额度" aria-label="Permalink to &quot;时间与额度&quot;">​</a></h2><p>审核模型与推理等级独立配置。审核等待是派发后的上限，审核预留是执行阶段提前留下的 任务余量，两者用途不同。180 秒设置仍受任务剩余期限约束，不保证提供方按时完成。 执行输出与审核输出容量分开；推理 token 是否计入输出以实际接口为准。</p><h2 id="本轮真实验证" tabindex="-1">本轮真实验证 <a class="header-anchor" href="#本轮真实验证" aria-label="Permalink to &quot;本轮真实验证&quot;">​</a></h2><p>原 DSH profile 的 <code>2 + 2</code> 返回 <code>4</code>：一次 Ark Flash low 执行，3531 毫秒， 没有规划、Jev、工具或最终审核调用；轨迹显示低风险跳过。 参考估值 0.033098 CNY，本次现金费用 0。</p><p>两次独立 GLM low 审核批次均在首请求遇到 <code>429 ServerOverloaded</code>，没有有效语义判定。 已停止批次并保留未知参考预留。因此本轮不能宣称真实最终审核或纠正质量已验收。</p><p>运行完成、跳过审核、审核批准、人工质量通过分别记录。Judge 不是质量保证。</p>',18)])])}const _=a(o,[["render",i]]);export{b as __pageData,_ as default};
